package dev.seaglass.core.backend

import android.graphics.RuntimeShader
import android.os.Build
import androidx.annotation.RequiresApi

/**
 * Binds the backend-agnostic 256-byte [SeaGlassUniformBlock] (`16 × vec4`) to an
 * Android 13+ (API 33+) [RuntimeShader] instance with zero heap allocations.
 */
@RequiresApi(Build.VERSION_CODES.TIRAMISU)
object SeaGlassAgslBinding {

    /**
     * Uploads all 16 `vec4` slots from [uniformBlock] into the target [shader]
     * generated by `SeaGlassShaderCompiler.compileForDialect(ShaderDialect.AGSL_100)`.
     */
    fun bindCompositeUniforms(shader: RuntimeShader, uniformBlock: SeaGlassUniformBlock) {
        val d = uniformBlock.data

        shader.setFloatUniform("uResolutionAndOrigin", d[0], d[1], d[2], d[3])
        shader.setFloatUniform("uOpticsPrimary", d[4], d[5], d[6], d[7])
        shader.setFloatUniform("uOpticsSecondary", d[8], d[9], d[10], d[11])
        shader.setFloatUniform("uLightAndMeta", d[12], d[13], d[14], d[15])

        // Node 0
        shader.setFloatUniform("uNode0Bounds", d[16], d[17], d[18], d[19])
        shader.setFloatUniform("uNode0Corners", d[32], d[33], d[34], d[35])
        shader.setFloatUniform("uNode0Tint", d[48], d[49], d[50], d[51])

        // Node 1
        shader.setFloatUniform("uNode1Bounds", d[20], d[21], d[22], d[23])
        shader.setFloatUniform("uNode1Corners", d[36], d[37], d[38], d[39])
        shader.setFloatUniform("uNode1Tint", d[52], d[53], d[54], d[55])

        // Node 2
        shader.setFloatUniform("uNode2Bounds", d[24], d[25], d[26], d[27])
        shader.setFloatUniform("uNode2Corners", d[40], d[41], d[42], d[43])
        shader.setFloatUniform("uNode2Tint", d[56], d[57], d[58], d[59])

        // Node 3
        shader.setFloatUniform("uNode3Bounds", d[28], d[29], d[30], d[31])
        shader.setFloatUniform("uNode3Corners", d[44], d[45], d[46], d[47])
        shader.setFloatUniform("uNode3Tint", d[60], d[61], d[62], d[63])
    }

    /**
     * Uploads uniforms for the lightweight AGSL sand-grain + frosted rim overlay shader.
     */
    fun bindSandGrainOverlayUniforms(shader: RuntimeShader, uniformBlock: SeaGlassUniformBlock) {
        bindCompositeUniforms(shader, uniformBlock)
    }
}
